class BitStatusUtil:
    EVEN_NUMBER_DIVISOR = 2
    MINIMUM_VALID_VALUE = 0

    @staticmethod
    def add(states, stat):
        BitStatusUtil.check([states, stat])
        return states | stat

    @staticmethod
    def has(states, stat):
        BitStatusUtil.check([states, stat])
        return BitStatusUtil.checkBitMatch(states, stat)

    @staticmethod
    def remove(states, stat):
        BitStatusUtil.check([states, stat])
        if BitStatusUtil.has(states, stat):
            return states ^ stat
        return states

    @staticmethod
    def check(args):
        for arg in args:
            BitStatusUtil.validateArg(arg)

    @staticmethod
    def validateArg(arg):
        if arg < BitStatusUtil.MINIMUM_VALID_VALUE:
            raise ValueError(f"{arg} must be greater than or equal to 0")
        if arg % BitStatusUtil.EVEN_NUMBER_DIVISOR != 0:
            raise ValueError(f"{arg} not even")

    @staticmethod
    def checkBitMatch(states, stat):
        return (states & stat) == stat
